"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["82289"],{62403(e){e.exports=JSON.parse('{"id":"F310","slug":"mbs-pass-through-month","name":"MBS Pass-Through Cash Flow for One Month","subject":"Fixed Income","section":"Securitized Products","topic":"Mortgage-backed securities (MBS)","level":"Intermediate","aliases":["mortgage backed securities","pass through rate","servicing fee","scheduled principal","prepayment"],"formula":{"latex":"\\\\text{Investor cash flow}=\\\\text{Interest at pass-through rate}+\\\\text{Scheduled principal}+\\\\text{Prepayment}","also":[],"text":"Investor cash flow = Balance x Pass-through rate / 12 + Scheduled principal + SMM x (Balance - Scheduled principal)"},"symbols":[{"symbol":"WAC","meaning":"Weighted average coupon of the mortgages in the pool","unit":"per year"},{"symbol":"Pass-through rate","meaning":"Rate paid to investors, which is the WAC less servicing and guarantee fees","unit":"per year"},{"symbol":"SMM","meaning":"Single monthly mortality, the share of the remaining balance prepaid this month","unit":"percent"},{"symbol":"n","meaning":"Remaining months","unit":"months"}],"when_to_use":"Use it to see where the monthly cash from a mortgage pool goes. Borrowers pay interest at the WAC and a level payment. Servicers keep a fee, and investors get the pass-through interest, the scheduled principal and any prepayments.","worked_example":{"problem":"A pool has a balance of 300,000,000, a WAC of 6.5%, a pass-through rate of 6.0%, 360 months remaining and a prepayment speed of 8% CPR. What does the investor receive this month?","inputs":{"bal":300000000,"wac":6.5,"pt":6,"n":360,"cpr":8},"steps":[{"label":"Monthly mortgage rate = WAC / 12","working":"0.065 / 12","value":"0.5417%"},{"label":"Level payment","working":"300,000,000 x 0.00541667 / (1-(1+0.00541667)^(-360))","value":"1,896,204.07"},{"label":"Interest paid by borrowers = balance x monthly rate","working":"300,000,000 x 0.00541667","value":"1,625,000.00"},{"label":"Scheduled principal = payment - interest","working":"1,896,204-1,625,000","value":"271,204.07"},{"label":"SMM = 1 - (1 - CPR)^(1/12)","working":"1-(1-0.08)^(1 / 12)","value":"0.692%"},{"label":"Prepayment = SMM x (balance - scheduled principal)","working":"0.00692438 x (300,000,000-271204)","value":"2,075,436.87"},{"label":"Interest to investors = balance x pass-through rate / 12","working":"300,000,000 x 0.06 / 12","value":"1,500,000.00"},{"label":"Servicing and guarantee fee kept = interest - investor interest","working":"1,625,000-1,500,000","value":"125,000.00"},{"label":"Total to investors","working":"1,500,000+271204+2,075,437","value":"3,846,640.94"},{"label":"New balance","working":"300,000,000-271204-2,075,437","value":"297,653,359.06"}],"answer":"Borrowers pay 1,896,204.07, of which 1,625,000.00 is interest. The servicer keeps 125,000.00. Investors receive 3,846,640.94: 1,500,000.00 of interest, 271,204.07 of scheduled principal and 2,075,436.87 of prepayments (SMM of 0.692%). The balance falls to 297,653,359.06."},"calculator":{"available":true,"inputs":[{"id":"bal","label":"Pool balance","unit":"money","type":"number","default":300000000,"hint":""},{"id":"wac","label":"Weighted average coupon","unit":"%","type":"number","default":6.5,"hint":""},{"id":"pt","label":"Pass-through rate","unit":"%","type":"number","default":6,"hint":""},{"id":"n","label":"Remaining months","unit":"months","type":"number","default":360,"hint":"","min":1},{"id":"cpr","label":"Conditional prepayment rate (CPR)","unit":"%","type":"number","default":8,"hint":""}],"checks":[{"expr":"wac>0 and pt<=wac and cpr<1","message":"The WAC must be above zero, the pass-through rate no higher than the WAC, and CPR below 100%."}],"steps":[{"id":"mr","label":"Monthly mortgage rate = WAC / 12","expr":"wac/12","format":"pct4"},{"id":"pmt","label":"Level payment","expr":"bal*mr/(1-(1+mr)^(-n))","format":"money"},{"id":"intr","label":"Interest paid by borrowers = balance x monthly rate","expr":"bal*mr","format":"money"},{"id":"sched","label":"Scheduled principal = payment - interest","expr":"pmt-intr","format":"money"},{"id":"smm","label":"SMM = 1 - (1 - CPR)^(1/12)","expr":"1-(1-cpr)^(1/12)","format":"pct3"},{"id":"prepay","label":"Prepayment = SMM x (balance - scheduled principal)","expr":"smm*(bal-sched)","format":"money"},{"id":"pint","label":"Interest to investors = balance x pass-through rate / 12","expr":"bal*pt/12","format":"money"},{"id":"serv","label":"Servicing and guarantee fee kept = interest - investor interest","expr":"intr-pint","format":"money"},{"id":"inv","label":"Total to investors","expr":"pint+sched+prepay","format":"money"},{"id":"newbal","label":"New balance","expr":"bal-sched-prepay","format":"money"}],"results":["inv","newbal"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pmt":1896204.070478896,"smm":6.924382628299419e-3,"inv":3846640.9382143733}},"finder":{"finds":"A mortgage pool\'s monthly cash flow to investors","needs":"Balance, WAC, pass-through rate, months, prepayment speed"},"related":[{"slug":"loan-payment","name":"Loan Payment (Amortization)"},{"slug":"psa-prepayment","name":"PSA Prepayment Speed, CPR and SMM"},{"slug":"weighted-average-life","name":"Weighted Average Life (WAL)"}],"related_ids":["F031","F311","F309"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Investor\xa0cash\xa0flow</mtext><mo>=</mo><mtext>Interest\xa0at\xa0pass-through\xa0rate</mtext><mo>+</mo><mtext>Scheduled\xa0principal</mtext><mo>+</mo><mtext>Prepayment</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Investor cash flow}=\\\\text{Interest at pass-through rate}+\\\\text{Scheduled principal}+\\\\text{Prepayment}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"maximum-drawdown","name":"Maximum Drawdown"},"next":{"slug":"ou-process-moments","name":"Mean-Reverting (Ornstein-Uhlenbeck) Process Moments"},"lesson":null,"total":522}')}}]);